namespace docking.widgets.imagepanel.actions;



using docking;
using docking.action;
using docking.widgets.imagepanel;

/**
 * Base class of DockingActions that require a NavigableImagePanel
 */
abstract class ImagePanelDockingAction : DockingAction {

	protected ImagePanel imagePanel;

	public ImagePanelDockingAction(string name, string owner, ImagePanel imagePanel) : base(name, owner)
    {

		Objects.requireNonNull(imagePanel, "ImagePanel cannot be null");

		this.imagePanel = imagePanel;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return imagePanel.getImage() != null;
	}

}
